{
  "schemaVersion": "2.0",
  "pageId": "E12-conditional-validation",
  "title": "E12 — Conditional / cross-field validation",
  "viewModel": {
    "form": {}
  },
  "locale": {
    "en": {}
  },
  "tree": {
    "id": "root",
    "type": "Stack",
    "props": {
      "direction": "vertical",
      "space": {
        "size": "md"
      },
      "fullWidth": true
    },
    "children": [
      {
        "id": "heading",
        "type": "Label",
        "props": {
          "text": "Why are you closing this account?",
          "size": "lg",
          "weight": "bold",
          "color": "textStrong"
        }
      },
      {
        "id": "reason",
        "type": "Form",
        "props": {
          "valueKey": "form",
          "fields": [
            {
              "name": "type",
              "label": "Reason",
              "kind": "string",
              "required": true
            },
            {
              "name": "details",
              "label": "Details",
              "kind": "string",
              "required": true,
              "minLength": 5
            }
          ]
        },
        "children": [
          {
            "id": "type",
            "type": "Select",
            "props": {
              "label": "Reason",
              "placeholder": "Select a reason",
              "value": "{{ vm.form.type }}",
              "required": true,
              "helperText": "{{ vm.errors.form.type }}",
              "options": [
                {
                  "value": "standard",
                  "label": "Standard reason"
                },
                {
                  "value": "other",
                  "label": "Other (please specify)"
                }
              ]
            },
            "actions": {
              "onChange": [
                {
                  "type": "state",
                  "mode": "set",
                  "path": "form.type",
                  "value": "{{ $event.value }}"
                },
                {
                  "type": "if",
                  "cond": "$event.value != 'other'",
                  "then": [
                    {
                      "type": "state",
                      "mode": "set",
                      "path": "form.details",
                      "value": ""
                    }
                  ]
                }
              ]
            }
          },
          {
            "id": "details",
            "type": "TextInput",
            "if": "vm.form.type = 'other'",
            "props": {
              "label": "Details",
              "placeholder": "Tell us more…",
              "value": "{{ vm.form.details }}",
              "required": true,
              "helperText": "{{ vm.errors.form.details }}"
            },
            "actions": {
              "onChange": [
                {
                  "type": "state",
                  "mode": "set",
                  "path": "form.details",
                  "value": "{{ $event.value }}"
                }
              ]
            }
          }
        ]
      },
      {
        "id": "submit",
        "type": "Button",
        "props": {
          "title": "Submit",
          "variant": "primary",
          "type": "filled"
        },
        "actions": {
          "onClick": [
            {
              "type": "if",
              "cond": "vm.form.type = 'other'",
              "then": [
                {
                  "type": "form.validate",
                  "form": "reason",
                  "scope": ["type", "details"]
                }
              ],
              "else": [
                {
                  "type": "form.validate",
                  "form": "reason",
                  "scope": ["type"]
                }
              ]
            },
            {
              "type": "if",
              "cond": "vm.valid.form = true",
              "then": [
                {
                  "type": "form.submit",
                  "formId": "reason",
                  "via": "corezoid",
                  "onError": [
                    {
                      "type": "notify",
                      "level": "error",
                      "title": "Could not submit"
                    }
                  ]
                }
              ],
              "else": [
                {
                  "type": "notify",
                  "level": "warn",
                  "title": "Please fix the highlighted fields"
                }
              ]
            }
          ]
        }
      }
    ]
  }
}

{
  "schemaVersion": "2.0",
  "pageId": "E11-wizard",
  "title": "E11 — Multi-step wizard form",
  "viewModel": {
    "step": 1,
    "wizard": {}
  },
  "locale": {
    "en": {}
  },
  "tree": {
    "id": "root",
    "type": "Stack",
    "props": {
      "direction": "vertical",
      "space": {
        "size": "lg"
      },
      "fullWidth": true
    },
    "children": [
      {
        "id": "indicator",
        "type": "Label",
        "props": {
          "text": "Step {{ vm.step }} of 3",
          "weight": "semibold",
          "color": "textMuted"
        }
      },
      {
        "id": "wizard",
        "type": "Form",
        "props": {
          "valueKey": "wizard",
          "fields": [
            {
              "name": "firstName",
              "label": "First name",
              "kind": "string",
              "required": true,
              "minLength": 2
            },
            {
              "name": "lastName",
              "label": "Last name",
              "kind": "string",
              "required": true
            },
            {
              "name": "email",
              "label": "Email",
              "kind": "string",
              "required": true,
              "minLength": 3
            },
            {
              "name": "company",
              "label": "Company",
              "kind": "string"
            },
            {
              "name": "role",
              "label": "Role",
              "kind": "string",
              "required": true
            }
          ]
        },
        "children": [
          {
            "id": "step-1",
            "type": "Stack",
            "if": "vm.step = 1",
            "props": {
              "direction": "vertical",
              "space": {
                "size": "sm"
              },
              "fullWidth": true
            },
            "children": [
              {
                "id": "firstName",
                "type": "TextInput",
                "props": {
                  "label": "First name",
                  "placeholder": "Ada",
                  "value": "{{ vm.wizard.firstName }}",
                  "required": true,
                  "helperText": "{{ vm.errors.wizard.firstName }}"
                },
                "actions": {
                  "onChange": [
                    {
                      "type": "state",
                      "mode": "set",
                      "path": "wizard.firstName",
                      "value": "{{ $event.value }}"
                    }
                  ]
                }
              },
              {
                "id": "lastName",
                "type": "TextInput",
                "props": {
                  "label": "Last name",
                  "placeholder": "Lovelace",
                  "value": "{{ vm.wizard.lastName }}",
                  "required": true,
                  "helperText": "{{ vm.errors.wizard.lastName }}"
                },
                "actions": {
                  "onChange": [
                    {
                      "type": "state",
                      "mode": "set",
                      "path": "wizard.lastName",
                      "value": "{{ $event.value }}"
                    }
                  ]
                }
              }
            ]
          },
          {
            "id": "step-2",
            "type": "Stack",
            "if": "vm.step = 2",
            "props": {
              "direction": "vertical",
              "space": {
                "size": "sm"
              },
              "fullWidth": true
            },
            "children": [
              {
                "id": "email",
                "type": "TextInput",
                "props": {
                  "label": "Email",
                  "type": "email",
                  "placeholder": "ada@example.com",
                  "value": "{{ vm.wizard.email }}",
                  "required": true,
                  "helperText": "{{ vm.errors.wizard.email }}"
                },
                "actions": {
                  "onChange": [
                    {
                      "type": "state",
                      "mode": "set",
                      "path": "wizard.email",
                      "value": "{{ $event.value }}"
                    }
                  ]
                }
              },
              {
                "id": "company",
                "type": "TextInput",
                "props": {
                  "label": "Company",
                  "placeholder": "Analytical Engines Ltd",
                  "value": "{{ vm.wizard.company }}"
                },
                "actions": {
                  "onChange": [
                    {
                      "type": "state",
                      "mode": "set",
                      "path": "wizard.company",
                      "value": "{{ $event.value }}"
                    }
                  ]
                }
              }
            ]
          },
          {
            "id": "step-3",
            "type": "Stack",
            "if": "vm.step = 3",
            "props": {
              "direction": "vertical",
              "space": {
                "size": "sm"
              },
              "fullWidth": true
            },
            "children": [
              {
                "id": "role",
                "type": "Select",
                "props": {
                  "label": "Role",
                  "placeholder": "Pick a role",
                  "value": "{{ vm.wizard.role }}",
                  "required": true,
                  "helperText": "{{ vm.errors.wizard.role }}",
                  "options": [
                    {
                      "value": "admin",
                      "label": "Administrator"
                    },
                    {
                      "value": "editor",
                      "label": "Editor"
                    },
                    {
                      "value": "viewer",
                      "label": "Viewer"
                    }
                  ]
                },
                "actions": {
                  "onChange": [
                    {
                      "type": "state",
                      "mode": "set",
                      "path": "wizard.role",
                      "value": "{{ $event.value }}"
                    }
                  ]
                }
              }
            ]
          }
        ]
      },
      {
        "id": "footer",
        "type": "Row",
        "props": {
          "gutter": "md",
          "justify": "between",
          "align": "middle"
        },
        "children": [
          {
            "id": "back",
            "type": "Button",
            "if": "vm.step > 1",
            "props": {
              "title": "Back",
              "type": "outlined",
              "variant": "secondary",
              "startIcon": "ArrowLeft2Icon"
            },
            "actions": {
              "onClick": [
                {
                  "type": "state",
                  "mode": "set",
                  "path": "step",
                  "value": "{{ vm.step - 1 }}"
                }
              ]
            }
          },
          {
            "id": "next",
            "type": "Button",
            "if": "vm.step < 3",
            "props": {
              "title": "Next",
              "variant": "primary",
              "type": "filled",
              "endIcon": "ArrowRight2Icon"
            },
            "actions": {
              "onClick": [
                {
                  "type": "if",
                  "cond": "vm.step = 1",
                  "then": [
                    {
                      "type": "form.validate",
                      "form": "wizard",
                      "scope": ["firstName", "lastName"]
                    }
                  ],
                  "else": [
                    {
                      "type": "form.validate",
                      "form": "wizard",
                      "scope": ["email", "company"]
                    }
                  ]
                },
                {
                  "type": "if",
                  "cond": "vm.valid.wizard = true",
                  "then": [
                    {
                      "type": "state",
                      "mode": "set",
                      "path": "step",
                      "value": "{{ vm.step + 1 }}"
                    }
                  ]
                }
              ]
            }
          },
          {
            "id": "submit",
            "type": "Button",
            "if": "vm.step = 3",
            "props": {
              "title": "Submit",
              "variant": "success",
              "type": "filled",
              "endIcon": "CheckIcon"
            },
            "actions": {
              "onClick": [
                {
                  "type": "form.validate",
                  "form": "wizard"
                },
                {
                  "type": "if",
                  "cond": "vm.valid.wizard = true",
                  "then": [
                    {
                      "type": "form.submit",
                      "formId": "wizard",
                      "via": "corezoid",
                      "onSuccess": [
                        {
                          "type": "if",
                          "cond": "$event.code >= 200 and $event.code < 300",
                          "then": [
                            {
                              "type": "notify",
                              "level": "success",
                              "title": "Registration submitted"
                            }
                          ]
                        }
                      ],
                      "onError": [
                        {
                          "type": "notify",
                          "level": "error",
                          "title": "Submit failed",
                          "helperText": "Please try again"
                        }
                      ]
                    }
                  ],
                  "else": [
                    {
                      "type": "state",
                      "mode": "set",
                      "path": "step",
                      "value": "{{ $exists(vm.errors.wizard.firstName) or $exists(vm.errors.wizard.lastName) ? 1 : ($exists(vm.errors.wizard.email) ? 2 : 3) }}"
                    },
                    {
                      "type": "notify",
                      "level": "warn",
                      "title": "Please fix the highlighted fields"
                    }
                  ]
                }
              ]
            }
          }
        ]
      }
    ]
  }
}

{
  "schemaVersion": "2.0",
  "pageId": "E22-data-grid",
  "title": "Server-driven data grid (filter + sort + paginate)",
  "viewModel": {
    "query": {
      "q": "",
      "sort": "name",
      "page": 1
    },
    "rows": [
      {
        "id": "1",
        "name": "Acme",
        "email": "ops@acme.com",
        "plan": "Pro"
      },
      {
        "id": "2",
        "name": "Globex",
        "email": "hi@globex.io",
        "plan": "Free"
      },
      {
        "id": "3",
        "name": "Initech",
        "email": "team@initech.com",
        "plan": "Pro"
      }
    ],
    "total": 42
  },
  "locale": {
    "en": {}
  },
  "tree": {
    "id": "root",
    "type": "Stack",
    "props": {
      "direction": "vertical",
      "size": "md",
      "fullWidth": true
    },
    "children": [
      {
        "id": "toolbar",
        "type": "Row",
        "props": {
          "gutter": "md",
          "align": "bottom",
          "wrap": true
        },
        "children": [
          {
            "id": "filter-col",
            "type": "Col",
            "props": {
              "flex": "1"
            },
            "children": [
              {
                "id": "filter",
                "type": "TextInput",
                "props": {
                  "label": "Search",
                  "value": "{{ vm.query.q }}",
                  "placeholder": "Search customers…",
                  "allowClear": true,
                  "startIcon": "SearchIcon"
                },
                "actions": {
                  "onChange": [
                    {
                      "type": "state",
                      "mode": "merge",
                      "path": "query",
                      "patch": {
                        "q": "{{ $event.value }}",
                        "page": 1
                      }
                    },
                    {
                      "type": "simapi.call",
                      "method": "customer/list",
                      "params": "{{ vm.query }}",
                      "assignTo": "page"
                    },
                    {
                      "type": "state",
                      "mode": "set",
                      "path": "rows",
                      "value": "{{ $result.page.rows }}"
                    },
                    {
                      "type": "state",
                      "mode": "set",
                      "path": "total",
                      "value": "{{ $result.page.total }}"
                    }
                  ]
                }
              }
            ]
          },
          {
            "id": "sort-col",
            "type": "Col",
            "props": {
              "flex": "0 0 200px"
            },
            "children": [
              {
                "id": "sort",
                "type": "Select",
                "props": {
                  "value": "{{ vm.query.sort }}",
                  "label": "Sort by",
                  "options": [
                    {
                      "value": "name",
                      "label": "Name"
                    },
                    {
                      "value": "email",
                      "label": "Email"
                    },
                    {
                      "value": "plan",
                      "label": "Plan"
                    }
                  ]
                },
                "actions": {
                  "onChange": [
                    {
                      "type": "state",
                      "mode": "merge",
                      "path": "query",
                      "patch": {
                        "sort": "{{ $event.value }}",
                        "page": 1
                      }
                    },
                    {
                      "type": "simapi.call",
                      "method": "customer/list",
                      "params": "{{ vm.query }}",
                      "assignTo": "page"
                    },
                    {
                      "type": "state",
                      "mode": "set",
                      "path": "rows",
                      "value": "{{ $result.page.rows }}"
                    },
                    {
                      "type": "state",
                      "mode": "set",
                      "path": "total",
                      "value": "{{ $result.page.total }}"
                    }
                  ]
                }
              }
            ]
          }
        ]
      },
      {
        "id": "grid",
        "type": "Table",
        "props": {
          "dataSource": "{{ vm.rows }}",
          "rowKey": "id",
          "hoverable": true,
          "striped": true,
          "columns": [
            {
              "key": "name",
              "title": "Name",
              "dataIndex": "name",
              "align": "left"
            },
            {
              "key": "email",
              "title": "Email",
              "dataIndex": "email",
              "align": "left"
            },
            {
              "key": "plan",
              "title": "Plan",
              "dataIndex": "plan",
              "align": "left"
            }
          ]
        }
      },
      {
        "id": "pager",
        "type": "Pagination",
        "props": {
          "total": "{{ vm.total }}",
          "current": "{{ vm.query.page }}",
          "pageSize": 10,
          "align": "right"
        },
        "actions": {
          "onChange": [
            {
              "type": "state",
              "mode": "merge",
              "path": "query",
              "patch": {
                "page": "{{ $event }}"
              }
            },
            {
              "type": "simapi.call",
              "method": "customer/list",
              "params": "{{ vm.query }}",
              "assignTo": "page"
            },
            {
              "type": "state",
              "mode": "set",
              "path": "rows",
              "value": "{{ $result.page.rows }}"
            },
            {
              "type": "state",
              "mode": "set",
              "path": "total",
              "value": "{{ $result.page.total }}"
            }
          ]
        }
      }
    ]
  }
}

{
