    "tab": "overview",
    "accounts": [
      {
        "id": "1",
        "name": "Acme",
        "balance": 1200
      },
      {
        "id": "2",
        "name": "Globex",
        "balance": -50
      },
      {
        "id": "3",
        "name": "Initech",
        "balance": 640
      }
    ],
    "settings": {
      "compact": false,
      "currency": "USD"
    }
  },
  "locale": {
    "en": {}
  },
  "tree": {
    "id": "root",
    "type": "Stack",
    "props": {
      "direction": "vertical",
      "size": "md",
      "fullWidth": true
    },
    "children": [
      {
        "id": "tabs",
        "type": "Tabs",
        "props": {
          "value": "{{ vm.tab }}",
          "variant": "auto"
        },
        "actions": {
          "onChange": [
            {
              "type": "state",
              "mode": "set",
              "path": "tab",
              "value": "{{ $event }}"
            }
          ]
        },
        "children": [
          {
            "id": "tab-overview",
            "type": "TabItem",
            "props": {
              "value": "overview",
              "title": "Overview",
              "startIcon": "HomeIcon"
            }
          },
          {
            "id": "tab-accounts",
            "type": "TabItem",
            "props": {
              "value": "accounts",
              "title": "Accounts",
              "badge": {
                "value": "{{ $count(vm.accounts) }}"
              }
            }
          },
          {
            "id": "tab-settings",
            "type": "TabItem",
            "props": {
              "value": "settings",
              "title": "Settings",
              "startIcon": "SettingsIcon"
            }
          }
        ]
      },
      {
        "id": "panel-overview",
        "type": "Row",
        "if": "vm.tab = 'overview'",
        "props": {
          "gutter": "md"
        },
        "children": [
          {
            "id": "stat-total",
            "type": "Col",
            "props": {
              "span": 12
            },
            "children": [
              {
                "id": "stat-total-card",
                "type": "Card",
                "props": {
                  "variant": "border",
                  "size": "md",
                  "fullWidth": true,
                  "accent": "primary"
                },
                "children": [
                  {
                    "id": "stat-total-label",
                    "type": "Label",
                    "props": {
                      "text": "Total balance",
                      "color": "textMuted",
                      "size": "sm"
                    }
                  },
                  {
                    "id": "stat-total-value",
                    "type": "Label",
                    "props": {
                      "text": "{{ $sum(vm.accounts.balance) & ' ' & vm.settings.currency }}",
                      "size": "xl",
                      "weight": "bold",
                      "color": "textStrong"
                    }
                  }
                ]
              }
            ]
          },
          {
            "id": "stat-count",
            "type": "Col",
            "props": {
              "span": 12
            },
            "children": [
              {
                "id": "stat-count-card",
                "type": "Card",
                "props": {
                  "variant": "border",
                  "size": "md",
                  "fullWidth": true
                },
                "children": [
                  {
                    "id": "stat-count-label",
                    "type": "Label",
                    "props": {
                      "text": "Accounts",
                      "color": "textMuted",
                      "size": "sm"
                    }
                  },
                  {
                    "id": "stat-count-value",
                    "type": "Label",
                    "props": {
                      "text": "{{ $count(vm.accounts) }}",
                      "size": "xl",
                      "weight": "bold",
                      "color": "textStrong"
                    }
                  }
                ]
              }
            ]
          }
        ]
      },
      {
        "id": "panel-accounts",
        "type": "Stack",
        "if": "vm.tab = 'accounts'",
        "props": {
          "direction": "vertical",
          "size": "xs",
          "fullWidth": true
        },
        "children": [
          {
            "id": "wacc",
            "type": "Card",
            "for": {
              "items": "vm.accounts",
              "as": "acc",
              "keyBy": "id"
            },
            "props": {
              "variant": "border",
              "size": "{{ vm.settings.compact ? 'xs' : 'sm' }}",
              "fullWidth": true
            },
            "children": [
              {
                "id": "wacc-row",
                "type": "Stack",
                "props": {
                  "direction": "horizontal",
                  "align": "center",
                  "justify": "between",
                  "size": "md",
                  "fullWidth": true
                },
                "children": [
                  {
                    "id": "wacc-name",
                    "type": "Label",
                    "props": {
                      "text": "{{ $acc.name }}",
                      "weight": "medium",
                      "color": "textStrong"
                    }
                  },
                  {
                    "id": "wacc-balance",
                    "type": "Label",
                    "props": {
                      "text": "{{ $acc.balance }}",
                      "color": "textSecondary"
                    }
                  },
                  {
                    "id": "wacc-open",
                    "type": "Button",
                    "props": {
                      "title": "Open",
                      "variant": "secondary",
                      "type": "text",
                      "size": "sm"
                    },
                    "actions": {
                      "onClick": [
                        {
                          "type": "navigate.local",
                          "to": "account-detail",
                          "query": {
                            "id": "{{ $acc.id }}"
                          },
                          "history": "push"
                        }
                      ]
                    }
                  }
                ]
              }
            ]
          }
        ]
      },
      {
        "id": "panel-settings",
        "type": "Stack",
        "if": "vm.tab = 'settings'",
        "props": {
          "direction": "vertical",
          "size": "md",
          "fullWidth": true
        },
        "children": [
          {
            "id": "compact-toggle",
            "type": "Toggle",
            "props": {
              "value": "{{ vm.settings.compact }}",
              "labelPosition": "right"
            },
            "actions": {
              "onChange": [
                {
                  "type": "state",
                  "mode": "merge",
                  "path": "settings",
                  "patch": {
                    "compact": "{{ vm.settings.compact ? false : true }}"
                  }
                }
              ]
            },
            "children": [
              {
                "id": "compact-label",
                "type": "Label",
                "props": {
                  "text": "Compact rows"
                }
              }
            ]
          },
          {
            "id": "settings-hint",
            "type": "Label",
            "props": {
              "text": "Compact mode is {{ vm.settings.compact ? 'on' : 'off' }} · currency {{ vm.settings.currency }}",
              "color": "textMuted"
            }
          }
        ]
      }
    ]
  }
}

